"use client"

import { useState, useEffect, useCallback } from "react"
import {
  Box,
  Typography,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  CircularProgress,
  TableFooter,
  TablePagination,
  Button,
  Card,
  CardContent,
  Chip,
  Stack,
  Alert,
  Container,
  useTheme,
  useMediaQuery,
  Avatar,
  IconButton,
  Tooltip,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Grid,
} from "@mui/material"
import {
  Business,
  Person,
  LocationOn,
  Phone,
  Store,
  Download,
  Visibility,
  Add,
  Close,
} from "@mui/icons-material"
import { motion } from "framer-motion"
import axios from "axios"
import { useAuth } from "../auth/AuthContext"
import AddDealers from "./AddDealers"

// Color palette
const COLORS = {
  primary: '#8d0638ff',
  secondary: '#667eea',
  background: '#f8fafc',
  surface: '#ffffff',
  text: {
    primary: '#1a202c',
    secondary: '#718096'
  }
}

function DealerList() {
  const { user } = useAuth()
  const [dealers, setDealers] = useState([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState("")
  const [page, setPage] = useState(0)
  const [rowsPerPage, setRowsPerPage] = useState(10)
  const [openAddModal, setOpenAddModal] = useState(false)
  const [selectedDealer, setSelectedDealer] = useState(null)
  const [openDetailsModal, setOpenDetailsModal] = useState(false)

  const theme = useTheme()
  const isMobile = useMediaQuery(theme.breakpoints.down("md"))

  const fetchData = useCallback(async () => {
    try {
      if (!user || !user.emp_id || !user.tenent_id) {
        setError("User is not authenticated")
        setLoading(false)
        return
      }

      const dealerResponse = await axios.get(
        "http://localhost:5000/SAFEGUARD/src/dealer/get_dealers.php",
        { params: { empId: user.emp_id, role: user.role } },
      )

      if (!dealerResponse.data.success) {
        setError(dealerResponse.data.message)
        setLoading(false)
        return
      }

      setDealers(dealerResponse.data.data.reverse())
    } catch (err) {
      setError("Error fetching dealer data")
      console.error("Error:", err)
    } finally {
      setLoading(false)
    }
  }, [user])

  useEffect(() => {
    fetchData()
  }, [fetchData])

  const handleChangePage = (event, newPage) => {
    setPage(newPage)
  }

  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10))
    setPage(0)
  }

  const handleOpenDetails = (dealer) => {
    setSelectedDealer(dealer)
    setOpenDetailsModal(true)
  }

  const formatDateTime = (dateStr) => {
    if (!dateStr) return '-'
    try {
      const d = new Date(dateStr)
      if (isNaN(d.getTime())) return dateStr
      return d.toLocaleDateString("en-GB", {
        day: "2-digit",
        month: "short",
        year: "numeric"
      }) + " " + d.toLocaleTimeString("en-IN", {
        hour: "2-digit",
        minute: "2-digit",
        hour12: true
      })
    } catch {
      return dateStr
    }
  }

  const exportToCsv = () => {
    const csvRows = [
      [
        "Dealer ID",
        "Dealer Name",
        "Company Name",
        "Address",
        "Contact Info",
        "Email",
        "Remarks",
        "Created At",
        "Added By",
      ],
    ]

    dealers.forEach(({ DealerID, DealerName, Address, ContactInfo, CompanyName, MailId, Remarks, CreatedAt, CreateDate, AddedByName }) => {
      csvRows.push([
        `"${DealerID}"`,
        `"${DealerName}"`,
        `"${CompanyName}"`,
        `"${Address}"`,
        `"${ContactInfo}"`,
        `"${MailId}"`,
        `"${Remarks}"`,
        `"${formatDateTime(CreatedAt || CreateDate)}"`,
        `"${AddedByName}"`,
      ])
    })

    const csvContent = csvRows.map((row) => row.join(",")).join("\n")
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" })
    const link = document.createElement("a")
    const url = URL.createObjectURL(blob)
    link.href = url
    link.setAttribute("download", "dealers.csv")
    link.click()
    URL.revokeObjectURL(url)
  }

  if (loading) {
    return (
      <Container maxWidth="xl" sx={{ py: 3 }}>
        <Box sx={{ display: "flex", justifyContent: "center", alignItems: "center", py: 8 }}>
          <CircularProgress size={60} sx={{ mr: 2, color: COLORS.primary }} />
          <Typography variant="h6" color="text.secondary">
            Loading dealer data...
          </Typography>
        </Box>
      </Container>
    )
  }

  if (error) {
    return (
      <Container maxWidth="xl" sx={{ py: 3 }}>
        <Alert severity="error" sx={{ mb: 2, borderRadius: 2 }}>
          {error}
        </Alert>
      </Container>
    )
  }

  return (
    <Container maxWidth="xl" sx={{ py: 3, background: COLORS.background, minHeight: '100vh' }}>
      {/* Header Section */}
      <motion.div
        initial={{ opacity: 0, y: -20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5 }}
      >
        <Box sx={{ mb: 4 }}>
          <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
            <Avatar
              sx={{
                bgcolor: `${COLORS.primary}15`,
                color: COLORS.primary,
                mr: 2,
                width: 56,
                height: 56
              }}
            >
              <Store sx={{ fontSize: 28 }} />
            </Avatar>
            <Box>
              <Typography
                variant="h4"
                component="h1"
                gutterBottom
                sx={{
                  fontWeight: 700,
                  color: COLORS.primary,
                  mb: 0.5,
                }}
              >
                Dealer Management
              </Typography>
              <Typography variant="body1" color="text.secondary">
                Manage and track all dealer information with dynamic checkpoints
              </Typography>
            </Box>
          </Box>
        </Box>
      </motion.div>

      {/* Stats and Action Section */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5, delay: 0.1 }}
      >
        <Card sx={{ 
          mb: 4, 
          borderRadius: 3,
          border: `1px solid ${theme.palette.divider}`,
          background: COLORS.surface,
          boxShadow: '0 4px 20px rgba(0,0,0,0.08)'
        }}>
          <CardContent sx={{ p: 3 }}>
            <Stack
              direction={isMobile ? "column" : "row"}
              justifyContent="space-between"
              alignItems={isMobile ? "stretch" : "center"}
              spacing={3}
            >
              <Box>
                <Typography variant="h3" fontWeight={700} color={COLORS.primary} gutterBottom>
                  {dealers.length}
                </Typography>
                <Typography variant="body1" color="text.secondary" fontWeight={500}>
                  Total Dealers
                </Typography>
                <Typography variant="caption" color="text.secondary">
                  Active dynamic dealer records in the system
                </Typography>
              </Box>

              <Stack direction="row" spacing={2} alignItems="center">
                <Button
                  variant="contained"
                  onClick={() => setOpenAddModal(true)}
                  startIcon={<Add />}
                  sx={{
                    bgcolor: COLORS.primary,
                    borderRadius: 2,
                    px: 3,
                    py: 1.5,
                    fontWeight: 600,
                    "&:hover": { 
                      bgcolor: '#70042c',
                      transform: 'translateY(-1px)',
                      boxShadow: `0 6px 20px ${COLORS.primary}40`
                    },
                    transition: 'all 0.2s ease',
                    minWidth: 150,
                  }}
                >
                  Add Dealer
                </Button>

                <Button
                  variant="outlined"
                  onClick={exportToCsv}
                  startIcon={<Download />}
                  sx={{
                    borderColor: COLORS.secondary,
                    color: COLORS.secondary,
                    borderRadius: 2,
                    px: 3,
                    py: 1.5,
                    fontWeight: 600,
                    "&:hover": { 
                      borderColor: '#5a6fd8',
                      bgcolor: `${COLORS.secondary}10`,
                      transform: 'translateY(-1px)',
                    },
                    transition: 'all 0.2s ease',
                    minWidth: 140,
                  }}
                >
                  Export CSV
                </Button>
              </Stack>
            </Stack>
          </CardContent>
        </Card>
      </motion.div>

      {/* Dealers Table */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5, delay: 0.2 }}
      >
        <Card sx={{ 
          borderRadius: 3,
          border: `1px solid ${theme.palette.divider}`,
          background: COLORS.surface,
          boxShadow: '0 4px 20px rgba(0,0,0,0.08)',
          overflow: 'hidden'
        }}>
          <TableContainer>
            <Table>
              <TableHead>
                <TableRow sx={{ 
                  bgcolor: 'grey.50',
                  '& th': {
                    fontWeight: 600,
                    color: COLORS.text.primary,
                    fontSize: '0.875rem',
                    py: 2,
                    borderBottom: `2px solid ${theme.palette.divider}`
                  }
                }}>
                  <TableCell>Dealer ID</TableCell>
                  <TableCell>Company</TableCell>
                  <TableCell>Contact Person</TableCell>
                  <TableCell>Address</TableCell>
                  <TableCell>Contact</TableCell>
                  <TableCell>Email</TableCell>
                  <TableCell>Remarks</TableCell>
                  <TableCell>Created At</TableCell>
                  <TableCell>Added By</TableCell>
                  <TableCell align="center">Actions</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {dealers.slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage).map((dealer) => (
                  <TableRow
                    key={dealer.DealerID}
                    sx={{
                      "&:hover": { 
                        bgcolor: 'action.hover',
                        transform: 'scale(1)'
                      },
                      transition: 'all 0.2s ease',
                      '&:last-child td': { borderBottom: 0 }
                    }}
                  >
                    <TableCell>
                      <Chip 
                        label={dealer.DealerID} 
                        size="small" 
                        sx={{
                          bgcolor: `${COLORS.primary}15`,
                          color: COLORS.primary,
                          fontWeight: 600,
                          borderRadius: 1.5
                        }} 
                      />
                    </TableCell>
                    <TableCell>
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5 }}>
                        <Avatar sx={{ width: 32, height: 32, bgcolor: COLORS.secondary, fontSize: '0.875rem' }}>
                          <Business fontSize="small" />
                        </Avatar>
                        <Typography variant="body2" fontWeight={500} noWrap>
                          {dealer.CompanyName}
                        </Typography>
                      </Box>
                    </TableCell>
                    <TableCell>
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5 }}>
                        <Avatar sx={{ width: 32, height: 32, bgcolor: '#10b981', fontSize: '0.875rem' }}>
                          <Person fontSize="small" />
                        </Avatar>
                        <Typography variant="body2" noWrap>
                          {dealer.DealerName}
                        </Typography>
                      </Box>
                    </TableCell>
                    <TableCell>
                      <Tooltip title={dealer.Address} arrow>
                        <Typography variant="body2" sx={{ 
                          maxWidth: 200, 
                          overflow: "hidden", 
                          textOverflow: "ellipsis",
                          whiteSpace: 'nowrap'
                        }}>
                          {dealer.Address}
                        </Typography>
                      </Tooltip>
                    </TableCell>
                    <TableCell>
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                        <Phone fontSize="small" sx={{ color: 'text.secondary' }} />
                        <Typography variant="body2">
                          {dealer.ContactInfo}
                        </Typography>
                      </Box>
                    </TableCell>
                    <TableCell>
                      <Tooltip title={dealer.MailId} arrow>
                        <Typography variant="body2" sx={{ 
                          maxWidth: 150, 
                          overflow: "hidden", 
                          textOverflow: "ellipsis",
                          whiteSpace: 'nowrap'
                        }}>
                          {dealer.MailId}
                        </Typography>
                      </Tooltip>
                    </TableCell>
                    <TableCell>
                      <Tooltip title={dealer.Remarks} arrow>
                        <Typography variant="body2" sx={{ 
                          maxWidth: 150, 
                          overflow: "hidden", 
                          textOverflow: "ellipsis",
                          whiteSpace: 'nowrap'
                        }}>
                          {dealer.Remarks || '-'}
                        </Typography>
                      </Tooltip>
                    </TableCell>
                    <TableCell>
                      <Typography variant="body2" color="text.secondary" noWrap sx={{ fontSize: '0.8125rem' }}>
                        {formatDateTime(dealer.CreatedAt || dealer.CreateDate)}
                      </Typography>
                    </TableCell>
                    <TableCell>
                      <Chip 
                        label={dealer.AddedByName || dealer.AddedByEmpId || 'Admin'} 
                        size="small" 
                        sx={{
                          bgcolor: `${COLORS.secondary}15`,
                          color: COLORS.secondary,
                          fontWeight: 500,
                          borderRadius: 1.5
                        }} 
                      />
                    </TableCell>
                    <TableCell align="center">
                      <Tooltip title="View All Checkpoints" arrow>
                        <IconButton
                          size="small"
                          onClick={() => handleOpenDetails(dealer)}
                          sx={{
                            color: COLORS.primary,
                            bgcolor: `${COLORS.primary}10`,
                            '&:hover': { bgcolor: `${COLORS.primary}25` }
                          }}
                        >
                          <Visibility fontSize="small" />
                        </IconButton>
                      </Tooltip>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
              <TableFooter>
                <TableRow>
                  <TablePagination
                    rowsPerPageOptions={[5, 10, 25, 50]}
                    count={dealers.length}
                    rowsPerPage={rowsPerPage}
                    page={page}
                    onPageChange={handleChangePage}
                    onRowsPerPageChange={handleChangeRowsPerPage}
                    sx={{
                      "& .MuiTablePagination-toolbar": {
                        bgcolor: 'grey.50',
                      },
                    }}
                  />
                </TableRow>
              </TableFooter>
            </Table>
          </TableContainer>
        </Card>
      </motion.div>

      {/* Dynamic Add Dealer Modal */}
      <AddDealers
        open={openAddModal}
        onClose={() => setOpenAddModal(false)}
        onDealerAdded={() => fetchData()}
      />

      {/* Dynamic View Details Dialog */}
      {selectedDealer && (
        <Dialog
          open={openDetailsModal}
          onClose={() => setOpenDetailsModal(false)}
          maxWidth="md"
          fullWidth
        >
          <DialogTitle
            sx={{
              bgcolor: COLORS.primary,
              color: 'white',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'space-between',
              py: 2,
              px: 3,
            }}
          >
            <Box>
              <Typography variant="h6" fontWeight={700}>
                {selectedDealer.CompanyName || selectedDealer.DealerName}
              </Typography>
              <Typography variant="caption" sx={{ color: 'rgba(255,255,255,0.85)' }}>
                Dealer ID #{selectedDealer.DealerID} &bull; Complete Dynamic Checkpoint Record
              </Typography>
            </Box>
            <IconButton onClick={() => setOpenDetailsModal(false)} size="small" sx={{ color: 'white' }}>
              <Close />
            </IconButton>
          </DialogTitle>

          <DialogContent sx={{ p: 3, pt: 3 }}>
            <Box sx={{ mb: 3, display: 'flex', gap: 1.5, flexWrap: 'wrap', alignItems: 'center' }}>
              {(selectedDealer.CreatedAt || selectedDealer.CreateDate) && (
                <Chip
                  label={`Created: ${formatDateTime(selectedDealer.CreatedAt || selectedDealer.CreateDate)}`}
                  size="small"
                  variant="outlined"
                  sx={{ borderColor: COLORS.secondary, color: COLORS.secondary, fontWeight: 500 }}
                />
              )}
              {selectedDealer.LatLong && (
                <Chip
                  icon={<LocationOn />}
                  label={`GPS Coordinates: ${selectedDealer.LatLong}`}
                  size="small"
                  color="success"
                  variant="outlined"
                />
              )}
            </Box>

            <Typography variant="subtitle2" color="text.secondary" sx={{ mb: 2, fontWeight: 700, textTransform: 'uppercase', letterSpacing: 0.5 }}>
              Checkpoints Data
            </Typography>

            <Grid container spacing={2.5}>
              {selectedDealer.dynamicValues && selectedDealer.dynamicValues.length > 0 ? (
                selectedDealer.dynamicValues.map((dv, idx) => {
                  const isImage = dv.typeId === 4;
                  return (
                    <Grid item xs={12} sm={isImage ? 12 : 6} key={idx}>
                      <Card variant="outlined" sx={{ p: 2, borderRadius: 2, height: '100%', bgcolor: '#fbfcfd' }}>
                        <Typography variant="caption" color="text.secondary" fontWeight={600} display="block" gutterBottom>
                          {dv.description}
                          <Chip label={dv.typeName || 'Text'} size="small" sx={{ ml: 1, height: 18, fontSize: '0.65rem' }} />
                        </Typography>

                        {isImage && dv.value ? (
                          <Box sx={{ mt: 1 }}>
                            <img
                              src={dv.value}
                              alt={dv.description}
                              style={{ maxHeight: 200, maxWidth: '100%', borderRadius: 4, objectFit: 'contain' }}
                            />
                          </Box>
                        ) : (
                          <Typography variant="body1" fontWeight={500} sx={{ wordBreak: 'break-word' }}>
                            {dv.value ? String(dv.value) : <span style={{ color: '#aaa', fontStyle: 'italic' }}>Not provided</span>}
                          </Typography>
                        )}
                      </Card>
                    </Grid>
                  );
                })
              ) : (
                <Grid item xs={12}>
                  <Alert severity="info">No checkpoint values recorded for this dealer.</Alert>
                </Grid>
              )}
            </Grid>
          </DialogContent>

          <DialogActions sx={{ p: 2, px: 3, borderTop: '1px solid #eee' }}>
            <Button onClick={() => setOpenDetailsModal(false)} variant="outlined" sx={{ color: COLORS.primary, borderColor: COLORS.primary }}>
              Close
            </Button>
          </DialogActions>
        </Dialog>
      )}
    </Container>
  )
}

export default DealerList